const v = H.plot2d({ xMin: 0, xMax: 0.05, yMin: 0, yMax: Pmax });
v.grid(); v.axes();
const procName = proc === 0 ? "isothermal (T const)" : proc === 1 ? "isobaric (P const)" : "isochoric (V const)";
// reference isotherm (faint)
v.fn(V => (V > 1e-6 ? n * R * T / V : NaN), { color: H.colors.sub, width: 1.2 });
// the chosen process path (bold)
const pts = [];
if (proc === 0) { for (let i = 0; i <= 60; i++) { const V = Vlo + (Vhi - Vlo) * i / 60; pts.push([V, n * R * T / V]); } }
else if (proc === 1) { const Pc = n * R * T / Vmid; pts.push([Vlo, Pc]); pts.push([Vhi, Pc]); }
else { pts.push([Vmid, n * R * T / Vhi]); pts.push([Vmid, n * R * T / 0.008]); }
